export declare const luxuryGoldTheme = "/* \u9ED1\u91D1\u5962\u534E\u98CE\u683C */\n#wemd {\n    padding: 5px 22px;\n    max-width: 677px;\n    margin: 0 auto;\n    /* \u5F3A\u5236\u5B8B\u4F53/\u886C\u7EBF\u4F53\uFF0C\u79FB\u52A8\u7AEF\u663E\u793A\u4F18\u96C5\u5B57\u4F53\u7684\u5173\u952E */\n    font-family: \"Songti SC\", \"SimSun\", \"STSong\", \"Georgia\", serif;\n    color: #222;\n    background-color: transparent;\n    /* \u900F\u660E\u80CC\u666F\uFF0C\u517C\u5BB9\u5FAE\u4FE1\u6DF1\u8272\u6A21\u5F0F */\n    word-break: break-word;\n}\n\n/* \u6B63\u6587 - \u758F\u6717\u7684\u884C\u95F4\u8DDD */\n#wemd p {\n    margin: 30px 0;\n    line-height: 2.0;\n    text-align: justify;\n    color: #444;\n    font-size: 16px;\n}\n\n/* \u4E00\u7EA7\u6807\u9898 - \u6781\u7B80\u7559\u767D */\n#wemd h1 {\n    margin: 70px 0 50px;\n    text-align: center;\n}\n\n#wemd h1 .content {\n    font-size: 26px;\n    font-weight: normal;\n    color: #000;\n    display: block;\n    letter-spacing: 3px;\n    border-bottom: 1px solid #000;\n    /* \u7EAF\u9ED1\u7EC6\u7EBF */\n    padding-bottom: 20px;\n}\n\n#wemd h1 .prefix,\n#wemd h1 .suffix {\n    display: none;\n}\n\n/* \u4E8C\u7EA7\u6807\u9898 - \u91D1\u8272\u8FB9\u6846\u76D2\u5B50 */\n#wemd h2 {\n    margin: 50px 0 30px;\n    text-align: center;\n}\n\n#wemd h2 .content {\n    display: inline-block;\n    font-size: 19px;\n    font-weight: normal;\n    color: #9E8045;\n    /* \u590D\u53E4\u91D1 */\n    border-top: 1px solid #9E8045;\n    border-bottom: 1px solid #9E8045;\n    padding: 10px 24px;\n    letter-spacing: 1px;\n}\n\n#wemd h2 .prefix,\n#wemd h2 .suffix {\n    display: none;\n}\n\n/* \u4E09\u7EA7\u6807\u9898 - \u7EAF\u9ED1\u5927\u5199\u611F */\n#wemd h3 {\n    margin: 40px 0 20px;\n    text-align: center;\n}\n\n#wemd h3 .content {\n    font-size: 17px;\n    font-weight: bold;\n    color: #000;\n    text-transform: uppercase;\n    letter-spacing: 1px;\n}\n\n#wemd h3 .prefix,\n#wemd h3 .suffix {\n    display: none;\n}\n\n/* \u56DB\u7EA7\u6807\u9898 - \u91D1\u8272\u5C0F\u6807 */\n#wemd h4 {\n    margin: 30px 0 15px;\n    text-align: center;\n}\n\n#wemd h4 .content {\n    font-size: 16px;\n    font-weight: normal;\n    color: #9E8045;\n    border-bottom: 1px solid #eee;\n    padding-bottom: 4px;\n}\n\n#wemd h4 .prefix,\n#wemd h4 .suffix {\n    display: none;\n}\n\n/* \u5F15\u7528 - \u5C45\u4E2D\u886C\u7EBF\u659C\u4F53 */\n#wemd .multiquote-1,\n#wemd .multiquote-2,\n#wemd .multiquote-3 {\n    margin: 40px 0;\n    padding: 20px 30px;\n    background: #fff;\n    /* \u4FDD\u6301\u7EAF\u767D */\n    border: none;\n    text-align: center;\n    border-left: none;\n    /* \u53BB\u6389\u9ED8\u8BA4\u5DE6\u8FB9\u6846 */\n}\n\n#wemd .multiquote-1 p {\n    color: #666;\n    font-style: italic;\n    font-family: serif;\n    font-size: 15px;\n    line-height: 1.8;\n}\n\n#wemd .multiquote-2 {\n    margin: 38px 0;\n    padding: 18px 28px;\n    background: #fff;\n    border: none;\n    text-align: center;\n    border-left: 2px solid #9E8045;\n}\n\n#wemd .multiquote-2 p {\n    color: #666;\n    font-style: italic;\n    font-family: serif;\n    font-size: 15px;\n}\n\n#wemd .multiquote-3 {\n    margin: 36px 0;\n    padding: 16px 26px;\n    background: #fafafa;\n    border: none;\n    text-align: center;\n    border-left: 1px solid #9E8045;\n}\n\n#wemd .multiquote-3 p {\n    color: #666;\n    font-style: italic;\n    font-family: serif;\n    font-size: 15px;\n}\n\n/* \u5217\u8868 - \u7CBE\u81F4\u7684\u91D1\u70B9 */\n#wemd ul {\n    list-style: square;\n    /* \u65B9\u5757\u6BD4\u5706\u70B9\u66F4\u65F6\u5C1A */\n    padding-left: 20px;\n    margin: 20px 0;\n    color: #9E8045;\n}\n\n#wemd ul li {\n    margin-bottom: 10px;\n}\n\n#wemd li section {\n    color: #444;\n}\n\n/* \u6709\u5E8F\u5217\u8868 */\n#wemd ol {\n    list-style: decimal;\n    padding-left: 20px;\n    margin: 20px 0;\n    color: #9E8045;\n}\n\n#wemd ul ul {\n    list-style-type: circle;\n    color: #9E8045;\n    margin-top: 8px;\n}\n\n#wemd ol ol {\n    list-style-type: lower-roman;\n    color: #9E8045;\n}\n\n#wemd ol li {\n    margin-bottom: 10px;\n}\n\n#wemd ol li section {\n    color: #444;\n}\n\n/* \u94FE\u63A5 - \u91D1\u8272\u7EC6\u7EBF */\n#wemd a {\n    color: #000;\n    border-bottom: 1px solid #9E8045;\n    text-decoration: none;\n    transition: opacity 0.2s;\n}\n\n/* \u52A0\u7C97 - \u91D1\u8272\u9AD8\u4EAE */\n#wemd strong {\n    color: #9E8045;\n    font-weight: bold;\n    margin: 0 2px;\n}\n\n/* \u659C\u4F53 */\n#wemd em {\n    color: #9E8045;\n    font-style: italic;\n}\n\n/* \u52A0\u7C97\u659C\u4F53 */\n#wemd em strong {\n    color: #9E8045;\n    font-weight: bold;\n}\n\n/* \u9AD8\u4EAE - \u6DE1\u91D1\u80CC\u666F */\n#wemd mark {\n    background: rgba(158, 128, 69, 0.15);\n    color: #9E8045;\n    padding: 2px 6px;\n    border-bottom: 1px solid rgba(158, 128, 69, 0.3);\n}\n\n/* \u5220\u9664\u7EBF */\n#wemd del {\n    text-decoration: line-through;\n    color: #999;\n    text-decoration-color: #9E8045;\n}\n\n/* \u5206\u9694\u7EBF - \u6781\u7B80\u77ED\u7EBF */\n#wemd hr {\n    margin: 60px auto;\n    height: 1px;\n    background: #9E8045;\n    width: 40px;\n    border: none;\n}\n\n/* \u56FE\u7247 - \u7EAF\u51C0\u7559\u767D */\n#wemd img {\n    display: block;\n    margin: 50px auto;\n    width: 100%;\n    /* \u6781\u6DE1\u7684\u9634\u5F71\uFF0C\u51E0\u4E4E\u770B\u4E0D\u89C1\uFF0C\u589E\u52A0\u4E00\u70B9\u7ACB\u4F53\u611F */\n    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.06);\n}\n\n#wemd figcaption {\n    color: #999;\n    font-size: 12px;\n    margin-top: 15px;\n    text-align: center;\n    font-style: italic;\n    font-family: serif;\n}\n\n/* \n * \u884C\u5185\u4EE3\u7801 - \u9999\u69DF\u91D1\u540A\u724C\u98CE\u683C (\u4FEE\u590D\u91CD\u70B9) \n * \u6781\u6DE1\u7684\u91D1\u8272\u80CC\u666F + \u7EC6\u8FB9\u6846\uFF0C\u7CBE\u81F4\u611F\u62C9\u6EE1\n */\n#wemd p code,\n#wemd li code,\n#wemd td code,\n#wemd th code {\n    color: #9E8045;\n    /* \u6DF1\u91D1\u8272\u6587\u5B57 */\n    background: rgba(158, 128, 69, 0.06);\n    /* 6%\u900F\u660E\u5EA6\u7684\u91D1\u8272\u80CC\u666F */\n    border: 1px solid rgba(158, 128, 69, 0.2);\n    /* 20%\u900F\u660E\u5EA6\u7684\u91D1\u8272\u8FB9\u6846 */\n    padding: 2px 6px;\n    margin: 0 4px;\n    border-radius: 2px;\n    font-size: 14px;\n    font-family: serif;\n    /* \u4FDD\u6301\u886C\u7EBF\u4F53\u98CE\u683C */\n}\n\n/* \u4EE3\u7801\u5757 - \u6781\u7B80\u9ED1\u767D */\n/* \u4EE3\u7801\u5757 - \u6CE8\u610F\uFF1A\u4E0D\u8981\u8BBE\u7F6E color\uFF0C\u8BA9\u8BED\u6CD5\u9AD8\u4EAE\u4E3B\u9898\u63A7\u5236\u6587\u5B57\u989C\u8272 */\n#wemd pre code.hljs {\n    display: block;\n    padding: 20px;\n    background: #fcfcfc;\n    /* \u63A5\u8FD1\u7EAF\u767D */\n    /* color \u7531 .hljs \u8BED\u6CD5\u9AD8\u4EAE\u4E3B\u9898\u63A7\u5236 */\n    font-size: 13px;\n    line-height: 1.6;\n    border: 1px solid #eee;\n    font-family: serif;\n    /* \u7279\u610F\u4F7F\u7528\u886C\u7EBF\u4F53\u663E\u793A\u4EE3\u7801\uFF0C\u6781\u5177\u827A\u672F\u611F */\n    overflow-x: auto;\n    white-space: pre;\n  min-width: max-content;\n}\n\n/* \u5982\u679C\u6CA1\u6709\u8BED\u6CD5\u9AD8\u4EAE\uFF0C\u8BBE\u7F6E\u9ED8\u8BA4\u6DF1\u7070\u8272 */\n#wemd pre code:not(.hljs) {\n    color: #333;\n    background: #fcfcfc;\n    border: 1px solid #eee;\n}\n\n/* \u8868\u683C - \u6781\u7B80\u7EBF\u6761 */\n#wemd table {\n    width: 100%;\n    border-collapse: collapse;\n    margin: 40px 0;\n    font-size: 14px;\n    border-top: 1px solid #000;\n    border-bottom: 1px solid #000;\n}\n\n#wemd table tr th {\n    color: #9E8045;\n    font-weight: normal;\n    border-bottom: 1px solid #eee;\n    padding: 12px 10px;\n    text-align: center;\n}\n\n#wemd table tr td {\n    border-bottom: 1px solid #eee;\n    padding: 12px 10px;\n    color: #555;\n    text-align: center;\n}\n\n/* \u811A\u6CE8 */\n#wemd .footnote-word,\n#wemd .footnote-ref {\n    color: #9E8045;\n}\n\n#wemd .footnotes-sep {\n    border-top: 1px solid #eee;\n    padding-top: 20px;\n    margin-top: 60px;\n    font-size: 12px;\n    color: #ccc;\n    text-align: center;\n}\n\n#wemd .footnote-num {\n    font-weight: bold;\n    color: #9E8045;\n    margin-right: 4px;\n}\n\n#wemd .footnote-item p {\n    color: #999;\n    font-size: 12px;\n    margin: 4px 0;\n}\n\n/* \u516C\u5F0F */\n#wemd .block-equation > svg {\n    max-width: 100% !important;\n}\n\n#wemd .inline-equation > svg {\n    max-width: 100%;\n    vertical-align: middle;\n}\n\n/* \u63D0\u793A\u5757 - \u9ED1\u91D1\u5962\u534E\u98CE\u683C */\n#wemd .callout {\n    margin: 40px 0;\n    padding: 20px 30px;\n    background: #fff;\n    border: 1px solid rgba(158, 128, 69, 0.3);\n    border-radius: 2px;\n}\n\n#wemd .callout-title {\n    font-weight: normal;\n    margin-bottom: 10px;\n    color: #9E8045;\n    font-family: serif;\n    letter-spacing: 1px;\n    font-size: 15px;\n}\n\n#wemd .callout-icon { margin-right: 8px;\n    margin-right: 6px;\n}\n\n#wemd .callout-note { border-left: 3px solid #9E8045; }\n#wemd .callout-tip { border-left: 3px solid #9E8045; }\n#wemd .callout-important { border-left: 3px solid #9E8045; }\n#wemd .callout-warning { border-left: 3px solid #D98C45; }\n#wemd .callout-caution { border-left: 3px solid #B33D25; }\n\n/* Imageflow CSS */\n#wemd .imageflow-layer1 {\n  margin-top: 1em;\n  margin-bottom: 0.5em;\n  /* white-space: normal; */\n  border: 0px none;\n  padding: 0px;\n  overflow: hidden;\n}\n\n#wemd .imageflow-layer2 {\n  white-space: nowrap;\n  width: 100%;\n  overflow-x: scroll;\n}\n\n#wemd .imageflow-layer3 {\n  display: inline-block;\n  word-wrap: break-word;\n  white-space: normal;\n  vertical-align: top;\n  width: 80%;\n  margin-right: 10px;\n  flex-shrink: 0;\n}\n\n#wemd .imageflow-img {\n  display: block;\n  width: 100%;\n  height: auto;\n  max-height: 300px;\n  object-fit: contain;\n  border-radius: 4px;\n}\n\n#wemd .imageflow-caption {\n  text-align: center;\n  margin-top: 0px;\n  padding-top: 0px;\n  color: #888;\n}\n";
